class Logger {
  static tag() {
    return this.name;
  }
  format(msg) {
    return `${this.prefix}:${msg}`;
  }
}

class AppLogger extends Logger {
  static tag() {
    return super.tag().toUpperCase();
  }
  constructor(prefix) {
    super();
    this.prefix = prefix;
  }
  format(msg) {
    return `[${super.format(msg)}]`;
  }
}

const app = new AppLogger("api");
console.log(AppLogger.tag());
console.log(app.format("ok"));
console.log(app.format.call({ prefix: "db", format: () => "x" }, "up"));
